fn hex(s:&str)->Vec<u8>{s.as_bytes().chunks_exact(2).map(|v|u8::from_str_radix(std::str::from_utf8(v).unwrap(),16).unwrap()).collect()}
fn inputs(p:&Path,n:&str)->Inputs{let manifest=p.join("logs/continuation-20261003").join(n);let bytes=fs::read(&manifest).unwrap();Inputs{project:p.into(),manifest,manifest_pin:BytePin{bytes:bytes.len()as u64,sha256:Sha256::digest(bytes).into()}}}
fn wait(r:&mut Runtime,page:UiPage){let end=Instant::now()+Duration::from_secs(15);while r.page()!=page{assert!(Instant::now()<end);r.poll();thread::sleep(Duration::from_millis(2));}}
fn ready(p:&Path)->Result<Runtime>{let mut r=Runtime::start_with_menu_skin(inputs(p,"r486-map-binding.json"),inputs(p,"r506-native-menu-skin-binding.json"))?;wait(&mut r,UiPage::Menu);Ok(r)}
fn close(r:&mut Runtime)->Result<()>{r.handle(Action::Close)?;wait(r,UiPage::Closed);ensure!(r.player_fixture_snapshot().workers_started==0,"no new socket fixture allowed");Ok(())}
fn z(b:&mut Vec<u8>,s:&[u8]){b.extend(s);b.push(0);}
fn cd(alias:&[u8],room_id:u32,state:u8,wide:bool)->Vec<u8>{
 let mut b=vec![205];b.extend(room_id.to_le_bytes());z(&mut b,alias);b.extend([1,4,1]);
 for n in if wide{[0xf1f2f3f4u32,0x80fffffc,0x7ffffffb]}else{[0,0,0]}{b.extend(n.to_le_bytes());}
 b.push(state);z(&mut b,if wide{b"ABCDEFGHIJKLMNOP"}else{b""});b.push(0);z(&mut b,b"Ready");b.extend(if wide{0xf1234567u32}else{0}.to_le_bytes());
 b.extend([255,0]);b.extend(if wide{0xe123abcdu32}else{0}.to_le_bytes());b.push(14);
 b.extend(if wide{[0,255,128,1,2,3,4,5,6,7,8,9]}else{[0;12]});b.extend(if wide{[0,1,2,3,127]}else{[0;5]});b.extend(1u32.to_le_bytes());b
}
fn d1(alias:&[u8],state:u8)->Vec<u8>{let mut b=vec![209];z(&mut b,alias);b.push(state);b}
